    description:
      "1924年開場の野球の聖地・阪神甲子園球場を「歴史と伝統」の角度で徹底ガイド。2024年100周年を経た球場の名前の由来(干支「甲子」)、約430本のツタ外壁の物語、アルプススタンド命名の経緯(1929年)、2026年4月から7年ぶりに復活したラッキーセブンのジェット風船、高校野球の聖地としての側面、伝統グルメまで、甲子園が他の球場と決定的に違う理由を解説します。",
