ベルーナドームは**「フレックスプライス制」**を採用しており、**試合ごとに価格カテゴリ（V／S／P／SP／SP+）が変動**します。**人気カード（巨人・ソフトバンク・楽天戦・GW・夏休み）はSP+カテゴリ**で、**平日デーゲームはVカテゴリ**で手頃に設定される傾向です。

